69	export class EnterPlanModeInvocation extends BaseToolInvocation<
70	  EnterPlanModeParams,
71	  ToolResult
72	> {
73	  private confirmationOutcome: ToolConfirmationOutcome | null = null;
74	
75	  constructor(
76	    params: EnterPlanModeParams,
77	    messageBus: MessageBus,
78	    toolName: string,
79	    toolDisplayName: string,
80	    private config: Config,
81	  ) {
82	    super(params, messageBus, toolName, toolDisplayName);
83	  }
84	
85	  getDescription(): string {
86	    return this.params.reason || 'Initiating Plan Mode';
87	  }
88	
89	  override async shouldConfirmExecute(
90	    abortSignal: AbortSignal,
91	  ): Promise<ToolInfoConfirmationDetails | false> {
92	    const decision = await this.getMessageBusDecision(abortSignal);
93	    if (decision === 'allow') {
94	      return false;
95	    }
96	
97	    if (decision === 'deny') {
98	      throw new Error(
99	        `Tool execution for "${
100	          this._toolDisplayName || this._toolName
101	        }" denied by policy.`,
102	      );
103	    }
104	
105	    // ask_user
106	    return {
107	      type: 'info',
108	      title: 'Enter Plan Mode',
109	      prompt:
110	        'This will restrict the agent to read-only tools to allow for safe planning.',
111	      onConfirm: async (outcome: ToolConfirmationOutcome) => {
112	        this.confirmationOutcome = outcome;
113	        // Policy updates are now handled centrally by the scheduler
114	      },
115	    };
116	  }
117	
118	  async execute({ abortSignal: _signal }: ExecuteOptions): Promise<ToolResult> {
119	    if (this.confirmationOutcome === ToolConfirmationOutcome.Cancel) {
120	      return {
121	        llmContent: 'User cancelled entering Plan Mode.',
122	        returnDisplay: 'Cancelled',
123	      };
124	    }
125	
126	    this.config.setApprovalMode(ApprovalMode.PLAN);
127	
128	    // Ensure plans directory exists so that the agent can write the plan file.
129	    // In sandboxed environments, the plans directory must exist on the host
130	    // before it can be bound/allowed in the sandbox.
131	    const plansDir = this.config.storage.getPlansDir();
132	    if (!fs.existsSync(plansDir)) {
133	      try {
134	        fs.mkdirSync(plansDir, { recursive: true });
135	      } catch (e) {
136	        // Log error but don't fail; write_file will try again later
137	        debugLogger.error(`Failed to create plans directory: ${plansDir}`, e);
138	      }
139	    }
140	
141	    return {
142	      llmContent: 'Switching to Plan mode.',
143	      returnDisplay: this.params.reason
144	        ? `Switching to Plan mode: ${this.params.reason}`
145	        : 'Switching to Plan mode',
146	    };
147	  }
148	}
