}", "newString": "/**
 * Resolves an untrusted plan file reference to an absolute path while enforcing
 * that it stays within the authorized plans directory.
 *
 * Plan references are relative to the plans directory, but the same directory is
 * surfaced to the model relative to the project root. To handle both forms (and
 * absolute paths) predictably, resolution is attempted in order:
 *   1. An absolute path is accepted only if it resolves within the plans dir.
 *   2. The path is resolved relative to the project root (this matches how the
 *      plans directory is displayed, e.g. `.gemini/plans/foo.md`).
 *   3. The path is resolved relative to the plans directory itself.
 *
 * Symbolic links are resolved (via `resolveToRealPath`) before the containment
 * check, so links escaping the plans directory are rejected.
 *
 * @param planPath The untrusted path to the plan file.
 * @param plansDir The authorized project plans directory.
 * @param projectRoot The root directory of the project.
 * @returns The resolved, validated absolute path to the plan file.
 * @throws If the reference is empty or resolves outside the plans directory.
 */
export function resolveAndValidatePlanPath(
  planPath: string,
  plansDir: string,
  projectRoot: string,
): string {
  const trimmedPath = planPath.trim();
  if (!trimmedPath) {
    throw new Error('Plan file path must be non-empty.');
  }

  const realPlansDir = resolveToRealPath(plansDir);

  // Strategy 1: Absolute path, accepted only if it stays within the plans dir.
  if (path.isAbsolute(trimmedPath)) {
    if (isSubpath(realPlansDir, resolveToRealPath(trimmedPath))) {
      return trimmedPath;
    }
    throw new Error(
      PlanErrorMessages.PATH_ACCESS_DENIED(planPath, realPlansDir),
    );
  }

  // Strategy 2: Relative to the project root (how the plans dir is displayed).
  const projectRootRelative = path.resolve(projectRoot, trimmedPath);
  if (isSubpath(realPlansDir, resolveToRealPath(projectRootRelative))) {
    return projectRootRelative;
  }

  // Strategy 3: Relative to the plans directory.
  const plansDirRelative = path.resolve(plansDir, trimmedPath);
  if (isSubpath(realPlansDir, resolveToRealPath(plansDirRelative))) {
    return plansDirRelative;
  }

  throw new Error(PlanErrorMessages.PATH_ACCESS_DENIED(planPath, realPlansDir));
}

/**
 * Validates a plan file path for safety (traversal) and existence.
 * @param planPath The untrusted path to the plan file.
 * @param plansDir The authorized project plans directory.
 * @param projectRoot The root directory of the project.
 * @returns An error message if validation fails, or null if successful.
 */
export async function validatePlanPath(
  planPath: string,
  plansDir: string,
  projectRoot: string,
): Promise<string | null> {
  try {
    const resolvedPath = resolveAndValidatePlanPath(
      planPath,
      plansDir,
      projectRoot,
    );

    if (!(await fileExists(resolvedPath))) {
