26	 * Resolves an untrusted plan file reference to an absolute path while enforcing
27	 * that it stays within the authorized plans directory.
28	 *
29	 * Plan references are relative to the plans directory, but the same directory is
30	 * surfaced to the model relative to the project root. To handle both forms (and
31	 * absolute paths) predictably, resolution is attempted in order:
32	 *   1. An absolute path is accepted only if it resolves within the plans dir.
33	 *   2. The path is resolved relative to the project root (this matches how the
34	 *      plans directory is displayed, e.g. `.gemini/plans/foo.md`).
35	 *   3. The path is resolved relative to the plans directory itself.
36	 *
37	 * Symbolic links are resolved (via `resolveToRealPath`) before the containment
38	 * check, so links escaping the plans directory are rejected.
39	 *
40	 * @param planPath The untrusted path to the plan file.
41	 * @param plansDir The authorized project plans directory.
42	 * @param projectRoot The root directory of the project.
43	 * @returns The resolved, validated absolute path to the plan file.
44	 * @throws If the reference is empty or resolves outside the plans directory.
45	 */
46	export function resolveAndValidatePlanPath(
47	  planPath: string,
48	  plansDir: string,
49	  projectRoot: string,
50	): string {
51	  const trimmedPath = planPath.trim();
52	  if (!trimmedPath) {
53	    throw new Error('Plan file path must be non-empty.');
54	  }
55	
56	  const realPlansDir = resolveToRealPath(plansDir);
57	
58	  // Strategy 1: Absolute path, accepted only if it stays within the plans dir.
59	  if (path.isAbsolute(trimmedPath)) {
60	    if (isSubpath(realPlansDir, resolveToRealPath(trimmedPath))) {
61	      return trimmedPath;
62	    }
63	    throw new Error(
64	      PlanErrorMessages.PATH_ACCESS_DENIED(planPath, realPlansDir),
65	    );
66	  }
67	
68	  // Strategy 2: Relative to the project root (how the plans dir is displayed).
69	  const projectRootRelative = path.resolve(projectRoot, trimmedPath);
70	  if (isSubpath(realPlansDir, resolveToRealPath(projectRootRelative))) {
71	    return projectRootRelative;
72	  }
73	
